// return the intersection point of the two lines.
static Point line_intersect(const Point& a, const Point& b,
                            const Point& p1, const Point& p2) {
    // Both segments are guaranteed non-degenerate at call sites.
    auto A1 = b.y() - a.y();
    auto B1 = a.x() - b.x();
    auto C1 = A1 * a.x() + B1 * a.y();
    auto A2 = p2.y() - p1.y();
    auto B2 = p1.x() - p2.x();
    auto C2 = A2 * p1.x() + B2 * p1.y();
    auto det = A1 * B2 - A2 * B1;
    // det != 0 for non-parallel lines (we only call this when the segment
    // straddles the half-plane boundary, which requires non-parallel).
    double x = CGAL::to_double((B2 * C1 - B1 * C2) / det);
    double y = CGAL::to_double((A1 * C2 - A2 * C1) / det);

    // Snap to segment (p1, p2): project (x, y) back onto the segment.
    // This prevents epsilon-off-segment issues when double rounding causes
    // the computed intersection to land slightly outside the segment.
    double px1 = CGAL::to_double(p1.x()), py1 = CGAL::to_double(p1.y());
    double px2 = CGAL::to_double(p2.x()), py2 = CGAL::to_double(p2.y());
    double dx = px2 - px1, dy = py2 - py1;
    double len2 = dx * dx + dy * dy;
    double t = (len2 > 0) ? ((x - px1) * dx + (y - py1) * dy) / len2 : 0.0;
    t = std::clamp(t, 0.0, 1.0);
    return Point(px1 + t * dx, py1 + t * dy);
}

