        // This gives the intersection point as a double without going through
        // CGAL's inexact Segment_2 intersection (which can be epsilon-off).
        double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
        double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
        double cx = CGAL::to_double(c.x()), cy = CGAL::to_double(c.y());
        double dx = CGAL::to_double(d.x()), dy = CGAL::to_double(d.y());

        double ux = bx - ax, uy = by - ay;
        double vx = dx - cx, vy = dy - cy;
        double wx = ax - cx, wy = ay - cy;

        double denom = ux * vy - uy * vx;
        double absd = std::abs(denom);
        if (absd < 1e-18) return '0';  // parallel

        double t = (vx * wy - vy * wx) / denom;
        double ix = ax + t * ux;
        double iy = ay + t * uy;

        // Check which segment cases apply using squared_distance comparisons.
        // These use the exact Epick predicates so the classification is robust.
        bool on_ab = (CGAL::squared_distance(a, b) >= CGAL::squared_distance(a, Point(ix, iy)) - TOL*TOL) &&
