        bool on_cd = (CGAL::squared_distance(c, d) >= CGAL::squared_distance(c, Point(ix, iy)) - TOL*TOL) &&
                     (CGAL::squared_distance(c, d) >= CGAL::squared_distance(d, Point(ix, iy)) - TOL*TOL);
        bool endpoint_on_ab = CGAL::squared_distance(a, Point(ix, iy)) < TOL*TOL ||
