        bool endpoint_on_cd = CGAL::squared_distance(c, Point(ix, iy)) < TOL*TOL ||
                              CGAL::squared_distance(d, Point(ix, iy)) < TOL*TOL;

        if (!on_ab || !on_cd) return '0';
        out_p = Point(ix, iy);
        if (endpoint_on_ab || endpoint_on_cd) return 'v';
        return '1';
