// for the geometric construction (must be EPECK or equivalent).
// Returns one of:
//   '0' - no intersection
//   'v' - endpoint touches the other segment (single point in out_p)
//   '1' - proper crossing (single point in out_p)
//   'e' - collinear overlap (two endpoints in out_p, out_q)
template<class PK, class EPK>
static char seg_seg_int(const PK& a, const PK& b,
                        const PK& c, const PK& d,
                        PK& out_p, PK& out_q) {
    // Use exact arithmetic for the construction (coordinates), then convert back.
    // Predicates stay on the kernel of PK (exact for both Epick and Epeck).
    CGAL::Cartesian_converter<decltype(a), EPK> to_epk;
    using SegEPK = typename EPK::Segment_2;
    auto inter = CGAL::intersection(to_epk(a), to_epk(b), to_epk(c), to_epk(d));
    if (!inter) return '0';
    if (const typename EPK::Point_2* ip = std::get_if<typename EPK::Point_2>(&*inter)) {
        out_p = CGAL::Cartesian_converter<EPK, decltype(a)>()(*ip);
        return '1';
    }
    if (const SegEPK* seg = std::get_if<SegEPK>(&*inter)) {
        out_p = CGAL::Cartesian_converter<EPK, decltype(a)>()(seg->source());
        out_q = CGAL::Cartesian_converter<EPK, decltype(a)>()(seg->target());
