// Reference: lines of InOut() in O'Rourke's C code.
template<class PK>
static InFlag in_out(const PK& /*p*/, InFlag inflag, int aHB, int bHA) {
    if      (aHB > 0) return InFlag::Pin;
    else if (bHA > 0) return InFlag::Qin;
    return inflag;
