    if (signed_area(Pr) < 0) std::reverse(Pr.begin(), Pr.end());
    if (signed_area(Qr) < 0) std::reverse(Qr.begin(), Qr.end());
    int a = leftmost_index(Pr);
    int b = leftmost_index(Qr);

    int aa = 0, ba = 0;
    InFlag inflag = InFlag::Unknown;
    bool first_point = true;
