    Epeck::Point_2 A = to_exact(a), B = to_exact(b);
    Epeck::Point_2 C = to_exact(c), D = to_exact(d);
    auto inter = CGAL::intersection(Epeck::Segment_2(A, B), Epeck::Segment_2(C, D));
    if (!inter) return '0';
    if (const Epeck::Point_2* ip = std::get_if<Epeck::Point_2>(&*inter)) {
        out_p = to_inexact(*ip);
        return '1';  // converted point is always distinct from endpoints with Epeck
    }
    if (const Epeck::Segment_2* seg = std::get_if<Epeck::Segment_2>(&*inter)) {
        out_p = to_inexact(seg->source());
        out_q = to_inexact(seg->target());
        return 'e';
    }
    return '0';
}

