        if (const Point* ip = std::get_if<Point>(&*inter)) {
            // Snap onto the source segment to prevent epsilon drift.
            double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
            double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
