            double dx = CGAL::to_double(d.x()), dy = CGAL::to_double(d.y());
            double px = CGAL::to_double(ip->x()), py = CGAL::to_double(ip->y());

            auto snap = [&](double x1, double y1, double x2, double y2) {
                double sdx = x2 - x1, sdy = y2 - y1;
                double len2 = sdx * sdx + sdy * sdy;
